                    Reg::ShiftLefts(vA0, vA0, SHR_NUM_FOR_FP32, preg);
                    Reg::Sub((AscendC::Reg::RegTensor<uint32_t>&)vA1, (AscendC::Reg::RegTensor<uint32_t>&)vA, vA0, preg);
